"""Frozen temporal probability method: raw metrics,audit and historical references."""
import argparse,json,math,statistics,hashlib,sys,csv
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.report_quality_speed_final import FIELDS,fmt,table
from scripts.search_quality_speed import save

def read(p):return json.loads(p.read_text())
def csvwrite(path,rows):
 with path.open('w',newline='') as stream:
  writer=csv.DictWriter(stream,fieldnames=list(rows[0]),lineterminator='\n');writer.writeheader();writer.writerows(rows)
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=a.output;plan=read(root/'quality/plan.json');done=read(root/'quality/completion.json');selection=read(root/'selection.json');assert done['complete'] and len(done['runs'])==18
 for path,sha in plan['source_sha256'].items():assert hashlib.sha256((ROOT/path).read_bytes()).hexdigest()==sha,path
 candidate=selection['candidates'][0];name=candidate['name'];config=read(ROOT/candidate['config']);assert hashlib.sha256((ROOT/candidate['config']).read_bytes()).hexdigest()==candidate['config_sha256']
 old=read(ROOT/'outputs/streamed_history_20261106/summary.json');fast=read(ROOT/'outputs/quality_speed_search_20261106/current_probe_summary.json');rows=[];layers=[];macro=[];audits=[]
 for ds,scenes in plan['datasets'].items():
  for scene in scenes:
   folder=root/'quality/runs'/name/ds/scene;r=read(folder/'result.json');t=r['timing'];q=r['quality']['values'];ref=read(ROOT/'outputs/quality_speed_search_20261106/current_probe_quality/runs/cp4_c10_prior_residual_middle18'/ds/scene/'result.json');previous=read(ROOT/'outputs/streamed_history_20261106/quality/runs/streamed_history_block64_calibrated'/ds/scene/'result.json')
   assert r['quality']['complete'] and r['input']==ref['input']==previous['input'] and r['quality_protocol']==ref['quality_protocol']==previous['quality_protocol'];assert all(math.isfinite(q[k]) for k in FIELDS) and abs(q['cd']-(q['acc']+q['comp'])/2)<1e-9
   assert all(r['config'][k]==v for k,v in config.items());assert t['warmup']==1 and t['repeats']==3 and len(t['samples'])==3 and t['median_seconds']==statistics.median(v['seconds'] for v in t['samples'])
   for key in ['cluster_fraction','layer_retentions','shared_value_features','rep_history_execution','rep_history_loss','dual_iterations','query_group_size','dense_special_queries']:assert r['config'][key]==ref['config'][key]
   monitor=read(root/'quality/monitors'/f'{name}_{ds}_{scene}.json');assert monitor['returncode']==0 and not monitor['same_gpu_overlap_detected'] and monitor['max_simultaneous_gpu_applications']==1
   lr=read(folder/'layers.json');assert len(lr)==24;shape=r['input']['shape'];np=r['frames']*(shape[-2]//14)*(shape[-1]//14);n=np+r['frames']*5
   for layer in lr:
    l=layer['layer'];assert layer['fine_clusters']==math.floor(.1*np) and layer['history_key_blocks']==math.ceil(np/64) and layer['history_key_block_size']==64 and layer['history_probabilities_used']==(l>0) and not layer['history_cross_layer_head_matching']
    assert layer['selected_edge_recompute_qk_per_head']==0 and layer['current_probability_probes']==(4 if l==0 else 0) and layer['history_evidence_probes']==(4 if 0<l<23 else 0) and layer['history_cache_written']==(l<23)
    physical=layer['direct_logical_main_qk_per_head']+layer['coarse_observation_qk_per_head']+layer['current_probe_qk_per_head']+layer['dense_special_query_physical_qk_per_head'];assert physical/n**2<=.25
    layers.append(dict(dataset=ds,scene=scene,layer=l,actual_unique_density=layer['actual_unique_density'],issued_logical_qk_dense_fraction=physical/n**2,current_full_key_probes=layer['current_probability_probes'],selected_recomputed_qk=0,history_cache_bytes=layer['history_probability_cache_bytes'],dense_buffers_allocated_bytes=layer['history_cache_allocated_dense_bytes'],raw_evidence_scratch_bytes=layer['history_evidence_scratch_peak_bytes'],patch_budget=layer['patch_budget'],unused_budget_mean=layer['unused_budget_mean'],**{f'state_{i}_clusters_mean':layer.get(f'state_{i}_clusters_mean') for i in [0,1,5,10]}))
   row=dict(dataset=ds,scene=scene,frames=r['frames'],**q,seconds=t['median_seconds'],warm_peak_allocated_gib=max(v['peak_allocated_gib'] for v in t['samples']),warm_peak_reserved_gib=max(v['peak_reserved_gib'] for v in t['samples']),including_cold_peak_allocated_gib=max(v['peak_allocated_gib'] for v in t['samples']+t['cold_samples']),cold_seconds=t['cold_samples'][0]['seconds'],actual_unique_density=statistics.mean(v['actual_unique_density'] for v in lr),cache_max_mib=max(v['history_probability_cache_bytes'] for v in lr)/2**20,allocated_dense_buffers_mib=max(v['history_cache_allocated_dense_bytes'] for v in lr)/2**20,evidence_scratch_max_mib=max(v['history_evidence_scratch_peak_bytes'] for v in lr)/2**20,speedup_vs_dense=None,speedup_reason='No paired Dense timing authorized;historical controls only');rows.append(row);save(folder/'reporting.json',row);audits.append(dict(dataset=ds,scene=scene,matched_input_checkpoint_protocol=True,isolated_gpu=True,frozen_source=True,previous_probability_used=True,extra_selected_qk_zero=True))
  rr=[v for v in rows if v['dataset']==ds];m=dict(dataset=ds,method=name,scenes=len(rr),**{k:statistics.mean(v[k] for v in rr) for k in FIELDS},seconds=statistics.mean(v['seconds'] for v in rr),warm_peak_allocated_gib=max(v['warm_peak_allocated_gib'] for v in rr),warm_peak_reserved_gib=max(v['warm_peak_reserved_gib'] for v in rr),including_cold_peak_allocated_gib=max(v['including_cold_peak_allocated_gib'] for v in rr),mean_cold_seconds=statistics.mean(v['cold_seconds'] for v in rr),actual_unique_density=statistics.mean(v['actual_unique_density'] for v in rr),cache_max_mib=max(v['cache_max_mib'] for v in rr),allocated_dense_buffers_mib=max(v['allocated_dense_buffers_mib'] for v in rr),evidence_scratch_max_mib=max(v['evidence_scratch_max_mib'] for v in rr),speedup_vs_dense=None)
  for label,reference in [('old_history',old['macro']),('fast4',fast['macro'])]:
   ref=next(v for v in reference if v['dataset']==ds);m['changes_percent_vs_'+label]={k:100*(m[k]/ref[k]-1) for k in FIELDS};m['recon_within2pct_vs_'+label]=all(m[k]>=.98*ref[k] if k=='f1' else m[k]<=1.02*ref[k] for k in ['acc','comp','cd','f1'])
  macro.append(m)
 validation=read(root/'final_rgb128.json');assert validation['config']==config;probability=[]
 for ds in ['scannet','tum']:
  screen=read(root/f'refine_{ds}.json');decision=read(root/f'decision_{ds}.json');baseline=statistics.mean(v['baseline']['relative_l1'] for v in screen['intrinsic']);best=decision['summary'][0];assert best['config']['gamma']==1. and best['config']['probes']==4
  probability.append(dict(dataset=ds,old_history_relative_l1=baseline,new_history_relative_l1=best['relative_l1'],relative_l1_reduction_percent=100*(1-best['relative_l1']/baseline),cosine=best['cosine'],mask_jaccard=best['mask_jaccard'],captured_mass_vs_teacher_mask=best['captured_mass_vs_reference'],projected_error_vs_dense=best['projected_error_vs_dense'],old_recorded_mask_error_vs_dense=best['baseline_recorded_mask_error_vs_dense']))
 profile=read(root/'final_profile/result.json');assert profile['config']==config and abs(sum(v['seconds'] for v in profile['stages'])-profile['full_gpu_event_seconds'])<1e-4
 save(root/'summary.json',dict(complete=True,macro=macro,old_history_reference=old['macro'],fast4_reference=fast['macro'],historical_controls=fast['historical_controls'],probability_same_qkv=probability,independent_rgb128=dict(seconds=validation['timing']['median_seconds'],all_key_relative_l1=statistics.mean(v['all_patch_prediction']['relative_l1'] for v in validation['probability_transfer']),mask_jaccard=statistics.mean(v['mask_jaccard'] for v in validation['probability_transfer'])),selection=selection,dense_speedup=None,dense_speedup_reason='No paired control rerun authorized'))
 save(root/'audit.json',dict(passed=True,runs=18,rows=audits));csvwrite(root/'per_scene.csv',rows);csvwrite(root/'per_layer.csv',layers);csvwrite(root/'macro.csv',[{k:v for k,v in m.items() if not isinstance(v,dict)} for m in macro]);csvwrite(root/'probability.csv',probability)
 compare=[]
 for ds in plan['datasets']:
  for label,refs in [('旧历史版（已有）',old['macro']),('快速全Key版（已有）',fast['macro']),('新历史版（本轮）',macro)]:compare += [dict(v,label=label) for v in refs if v['dataset']==ds]
 lines=['# 历史概率改进：持久细粒度分布与当前稀疏采样校准','','只对修改后的方法进行完整质量评测和正式计时。概率校准另记录过一次旧稀疏轨迹RGB诊断，不产生重复控制质量结果。7Scenes全七场景各128帧，ETH3D同11场景14–76帧；同checkpoint、完整输入列表及质量协议，pose+recon_unposed六项等场景宏平均。AUC/F1单位%，距离m，CD=(ACC+Comp)/2未平方。','',table(['数据集','方法','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %'],[[v['dataset'],v['label'],*[fmt(k,v[k]) for k in FIELDS]] for v in compare]),'', '## 概率是否更接近快速版','','以下为独立ScanNet/TUM RGB64同QKV回放，旧历史轨迹固定。快速版四探针全Key概率是本地诊断参照，不是几何GT。新Mask及缓存会在该QKV上滚动；它不是新方法完整神经网络轨迹。','',table(['独立RGB','旧历史相对L1','新历史相对L1','误差降低 %','概率cosine','Mask Jaccard','捕获概率/teacher Mask'],[[v['dataset'],*[f"{v[k]:.5f}" for k in ['old_history_relative_l1','new_history_relative_l1','relative_l1_reduction_percent','cosine','mask_jaccard','captured_mass_vs_teacher_mask']]] for v in probability]),'',f"另一个TUM128 RGB真实新版轨迹：全Key概率相对L1={statistics.mean(v['all_patch_prediction']['relative_l1'] for v in validation['probability_transfer']):.5f}，完整前向中位数{validation['timing']['median_seconds']:.5f}s。只采样每层4个Query组，不能声称全部组一致。相对L1仍约0.47，不是接近零；概率代理改进不保证几何六项改善。",'', '## 改动与边界','','保留10%簇、固定Head-sketch4 Value特征、History A状态损失与prior_residual执行、10/18/10%预算、16轮状态分配、256-Query共享Mask及全部特殊Query修正。细节见docs/experiments/teacher_guided_history.md。','', '1. 跨层保留全部Key的head-mean细粒度概率，不把未选中Key重置均匀。','2. 当前层只计算64-Key均值块及每块8个真实Key采样的四探针粗信息。共享Key特征近邻把采样分布变化传播到块内；概率迁移置信度与历史权重0.75使分布向当前均匀先验收缩。','3. 正式Attention复用已计算QK，保存四探针相对logit与未补偿选中分母；得到选中条件概率后更新历史并作块质量归一化。不另算选中QK，不用跨层Head对应。','4. 只有L0四探针全Keybootstrap，这是声明的额外当前信息；L1–23没有当前全KeyQuery概率扫描。L0不重复导出已知证据，L23不生成无人消费的缓存。','5. GPU微基准选择1stage替代2stage，数学不变；其余候选Kernel更慢、未采用。', '', '新历史规则是独立建模修改，不是声称与旧概率公式完全等价。跨层缓存不含Head维，但正式Attention及当前层证据暂存仍逐Head。保留未选中细节增加存储；历史信息获取不是零开销。','', '## 速度与显存','','每序列1预热+3次完整前向中位数，再等场景平均；GPU4/5/6逐卡独占监控。加载与CPU几何评估不计入模型前向；初始化、聚类、历史、特殊Query、预测头计入。','',table(['数据集','新历史 s','旧历史 s（历史批次）','快速版 s（历史批次）','热allocated峰值 GiB','含冷启动峰值 GiB','有效缓存 MiB','双buffer分配 MiB','证据暂存 MiB'],[[v['dataset'],f"{v['seconds']:.5f}",f"{next(x['seconds'] for x in old['macro'] if x['dataset']==v['dataset']):.5f}",f"{next(x['seconds'] for x in fast['macro'] if x['dataset']==v['dataset']):.5f}",*[f"{v[k]:.3f}" for k in ['warm_peak_allocated_gib','including_cold_peak_allocated_gib','cache_max_mib','allocated_dense_buffers_mib','evidence_scratch_max_mib']]] for v in macro]),'', 'Dense正式配对加速比N/A：遵守不重跑未修改对照的要求，旧历史时间不是本轮配对。Dense定义1.00x。SAF3R历史时间7Scenes6.705480s、ETH3D1.603858s，亦不能作为严格同期速度验收。','', '## 独立互斥Profile','','下面是另一轮128帧RGB事件profile，不能将其他运行的Kernel成本相加。AV行已经包含inline证据导出；缓存更新是本层消费已导出的证据并生产下一层cache，prediction是下一层消费历史，二者各计一次。','',table(['操作','秒','完整前向占比 %'],[[v['operation'],f"{v['seconds']:.6f}",f"{v['percent']:.3f}"] for v in profile['stages']]),'', '## 六指标变化及限制','','相对变化中AUC/F1正数更好，ACC/Comp/CD负数更好。未按本次几何分数再次调参。','',table(['数据集','参照',*[k+'变化 %' for k in FIELDS],'重建退化≤2%'],[[v['dataset'],label,*[f"{v['changes_percent_vs_'+label][k]:+.3f}" for k in FIELDS],v['recon_within2pct_vs_'+label]] for v in macro for label in ['old_history','fast4']]),'', '## 历史控制质量','','下表均复用旧结果；没有重跑Dense/SAF3R。旧控制缺checkpoint SHA，不能追认严格字节一致。SAF3R为lazy first-correspondence-head Top4/frame，非论文DINO Top-K。','',table(['数据集','历史控制','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %'],[[v['dataset'],v['method'],*[fmt(k,v[k]) for k in FIELDS]] for v in fast['historical_controls']]),'', '## 逐场景结果','',table(['数据集','场景','帧','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %','秒'],[[v['dataset'],v['scene'],v['frames'],*[fmt(k,v[k]) for k in FIELDS],f"{v['seconds']:.5f}"] for v in rows]),'', '7Scenes重建阈值/下采样0.05/0.0078125m；ETH3D0.25/0.0390625m。checkpoint SHA b08a43baa2db1aad9718e71e098831b8ad32f6f6826c802e9eb714aa34420969。11项数值测试通过；kernel/概率/Mask/RGB诊断六项几何均N/A并注明原因。源文件哈希、冻结配置、原始JSON、逐场景/逐层CSV、GPU监控与日志保留。约14GB中间QKV回放仅本地保留，Git归档不含该大文件，可由record_history_teacher_replay.py重新生成。']
 changes=[]
 for row in rows:
  reference=read(ROOT/'outputs/streamed_history_20261106/quality/runs/streamed_history_block64_calibrated'/row['dataset']/row['scene']/'result.json')['quality']['values'];changes.append(dict(dataset=row['dataset'],scene=row['scene'],changes_percent={k:100*(row[k]/reference[k]-1) for k in FIELDS},f1_pp=100*(row['f1']-reference['f1'])))
 save(root/'scene_changes.json',changes)
 validation_layers=[]
 for l in range(24):
  rr=[v for v in validation['probability_transfer'] if v['layer']==l];validation_layers.append(dict(layer=l,probability_relative_l1=statistics.mean(v['all_patch_prediction']['relative_l1'] for v in rr),mask_jaccard=statistics.mean(v['mask_jaccard'] for v in rr),captured_mass_vs_reference=statistics.mean(v['captured_mass_vs_reference'] for v in rr)))
 save(root/'validation_per_layer.json',validation_layers)
 extra=['','## 采用结论与失败定位','','这不是可直接替换原版的最终方案。概率平均误差改善，但ETH3D重建未通过相对旧历史版2%门槛；没有按测试分数继续选择参数，也未修改旧默认配置。','', 'ETH3D有7/11场景F1提高，但courtyard下降39.276个百分点、relief_2下降20.073个百分点，导致宏平均退化。courtyard的AUC3反而由20.4362%升至30.5358%，所以不能用相机平均改善推断点云重建改善。这些是现象定位，不足以确定哪一项新概率规则造成该退化；本轮是概率模块组合的整体评测，没有将其冒充逐项几何消融。','', '独立TUM128诊断在L11–16仍有较大误差，L14相对L1约0.927；L5/L7所选Mask捕获的teacher概率仅约teacher-Mask的68%/69%。因此平均L1约0.47不能称为所有层均已接近。误差累计和少量关键遗漏边是仍需验证的风险，不能认定为ETH3D失败的已证实因果解释。','', '新版完整前向比已有旧历史批次约增加10.8%（7Scenes）/3.5%（ETH3D），非同期配对。64-Key粗观测及概率迁移本身很便宜，但四探针导出增加正式Attention开销；只实现不重算QK，没有实现零开销历史复用。','', '原默认方法保留，实验版独立配置用于复现与后续研究。下一轮若继续研究，应在独立RGB上同时约束最差层概率误差、遗漏高概率质量与AV误差，不能继续只追平均L1或按本轮ETH3D分数调参。']
 lines+=extra
 (root/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(macro,indent=2))
if __name__=='__main__':main()
